"""v1.1 §18, §20 P: a project saved by StatExplore 1.0.0 (tests/fixtures/v1_0_project.sxp, generated by
tests/fixtures/make_v1_0_fixture.py from the v1.0.0 code) opens, keeps its history, reproduces its numbers,
exports, and is backed up before it is first overwritten in the v1.1 format."""
from __future__ import annotations

import shutil
from pathlib import Path

import pytest

from statexplore.analysis import mixed
from statexplore.analysis.builders import BY_KEY
from statexplore.analysis.framework import run_analysis
from statexplore.core.project import PROJECT_VERSION, Project
from statexplore.discovery.engine import create_run, execute, results_frame
from statexplore.discovery.space import SearchSettings

FIXTURE = Path(__file__).parent / "fixtures" / "v1_0_project.sxp"


@pytest.fixture
def v1(tmp_path):
    p = tmp_path / "old.sxp"
    shutil.copy2(FIXTURE, p)
    return p


def test_P_v1_project_opens_with_defaults(v1):
    proj = Project.open(v1)
    assert proj.loaded_version == 1
    ds = proj.dataset
    assert [r.kind for r in proj.results] == ["lm", "logistic", "anova_oneway", "mixed_model"]
    assert len(proj.searches) == 1 and proj.searches[0].status == "complete" and proj.searches[0].settings.family == ""
    assert proj.models[0].label == "v1 model" and proj.models[0].treatments == []
    v = ds.var("mood")
    assert v.measure.value == "ordinal" and v.measure_status == "source" and v.suggested_measure == ""
    assert ds.is_derived("x_c") and len(ds.filters) == 1 and ds.var("pid").role.value == "id"


@pytest.mark.r
def test_P_existing_models_are_not_silently_changed(v1, r_session):
    proj = Project.open(v1)
    ds = proj.dataset
    for old in proj.results[:3]:
        vars_ = {k: [x["name"] for x in v] for k, v in old.inputs["variables"].items()}
        new, _ = run_analysis(r_session, ds, BY_KEY[old.kind], vars_, old.inputs["options"])
        for a, b in zip(old.tables, new.tables):
            assert a.name == b.name and a.columns == b.columns
            assert len(a.rows) == len(b.rows)
            for ra, rb in zip(a.rows, b.rows):
                for xa, xb in zip(ra, rb):
                    if isinstance(xa, float):
                        assert xb == pytest.approx(xa, rel=1e-9, abs=1e-12), (old.title, a.name)
                    else:
                        assert xa == xb
    old = proj.results[3]
    spec = mixed.MixedSpec(**{k: v for k, v in old.inputs["spec"].items()})
    assert spec.family == "gaussian" and spec.engine == "lme4" and spec.inference == "satterthwaite"
    new, _ = mixed.run(r_session, ds, spec)
    fa = next(t for t in old.tables if t.name == "Fixed effects")
    fb = next(t for t in new.tables if t.name == "Fixed effects")
    assert [r[1] for r in fa.rows] == pytest.approx([r[1] for r in fb.rows], rel=1e-8)
    assert new.status == old.status


@pytest.mark.r
def test_P_discovery_still_runs_from_v1_settings(v1, tmp_path):
    proj = Project.open(v1)
    old = proj.searches[0]
    run = create_run(proj.dataset, SearchSettings.from_dict(old.settings.to_dict()))
    execute(run, proj.dataset, workdir=tmp_path / "w")
    a, b = results_frame(old), results_frame(run)
    assert run.family == old.family == "gaussian" and len(a) == len(b)
    assert b["p"].tolist() == pytest.approx(a["p"].tolist(), rel=1e-9)


def test_P_save_creates_backup_then_v2(v1, tmp_path):
    proj = Project.open(v1)
    original = v1.read_bytes()
    proj.save(v1)
    backup = v1.with_name("old.v1-backup.sxp")
    assert backup.read_bytes() == original and proj.backup_path == backup
    again = Project.open(v1)
    assert again.loaded_version == PROJECT_VERSION == 2 and len(again.results) == 4
    again.save(v1)                                   # no second backup of a v2 file
    assert sorted(p.name for p in tmp_path.iterdir()) == ["old.sxp", "old.v1-backup.sxp"]


def test_P_reports_export_from_v1_project(v1, tmp_path, qtbot):
    from statexplore.export import exporters

    proj = Project.open(v1)
    written = exporters.export(proj, [r.id for r in proj.results], tmp_path / "out", {"R", "xlsx", "docx", "pdf"})
    assert any(p.suffix == ".xlsx" for p in written) and any(p.suffix == ".docx" for p in written)
    assert any(p.suffix == ".pdf" for p in written)
